import { useState, useEffect } from 'react';

function useSimpleRouter() {
  const [path, setPath] = useState(window.location.pathname);

  useEffect(() => {
    function handlePopState() {
      setPath(window.location.pathname); // sync state when back/forward is used
    }
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  function navigate(newPath: string) {
    window.history.pushState({}, '', newPath); // changes the URL, no reload
    setPath(newPath); // triggers React to re-render with the new path
  }

  return { path, navigate };
}

function App() {
  const { path, navigate } = useSimpleRouter();

  return (
    <div>
      <button onClick={() => navigate('/about')}>About</button>
      <button onClick={() => navigate('/')}>Home</button>
      {path === '/' && <h1>Home Page</h1>}
      {path === '/about' && <h1>About Page</h1>}
    </div>
  );
}

