import { useParams, useSearchParams } from 'react-router-dom';
import { useState, useEffect } from 'react';

interface Product {
  id: number;
  name: string;
  price: number;
}

function ProductDetailPage() {
  const { id } = useParams(); // string, e.g. '42'
  const [searchParams] = useSearchParams();
  const referralSource = searchParams.get('ref'); // e.g. ?ref=newsletter

  const [product, setProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);

    async function loadProduct() {
      const productId = Number(id); // CONVERT before any numeric use,
                                       // exactly Module 7 lesson 3's rule
      const response = await fetch(`/api/products/${productId}`);
      const data: Product = await response.json();
      setProduct(data);
      setLoading(false);
    }

    loadProduct();
  }, [id]); // re-fetch if the URL's :id segment changes

  if (loading) return <p>Loading...</p>;
  if (!product) return <p>Product not found</p>;

  return (
    <div>
      <h1>{product.name}</h1>
      <p>${product.price}</p>
      {referralSource && <p>Thanks for visiting from {referralSource}!</p>}
    </div>
  );
}

