import { Navigate } from 'react-router-dom';
import { useAuth } from './AuthContext'; // Module 10 lesson 3's pattern

function ProtectedRoute({ children }: { children: React.ReactNode }) {
  const { user } = useAuth();

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  return children;
}

Using it to wrap specific routes in the router configuration:

const router = createBrowserRouter([
  { path: '/login', element: <LoginPage /> },
  {
    path: '/dashboard',
    element: (
      <ProtectedRoute>
        <DashboardPage />
      </ProtectedRoute>
    )
  }
]);

Navigate's replace prop ensures the redirect doesn't add a new entry to the browser's history stack, so clicking 'back' after being redirected to /login doesn't take the user back to the protected page they were just bounced from.

